inline bool AIGroup::getCenter(Coord3D *center)
{
    int count = 0;
    center->x = 0.0f;
    center->y = 0.0f;
    center->z = 0.0f;

    std::list<Object*>::iterator i;
    for (i = m_memberList.begin(); i != m_memberList.end(); ++i)
    {
        if ((*i)->isDisabledHeld())
            continue; // don't bother counting riders in the center calculation
        if (!(*i)->isMobile())
            continue;
        AIUpdateInterface *ai = (*i)->getAI();
        if (ai)
        {
            const Coord3D *objPos = (*i)->getPosition();
            center->x += objPos->x;
            center->y += objPos->y;
            center->z += objPos->z;
            ++count;
        }
    }

    if (count == 0 && !m_memberList.empty())
    {
        for (i = m_memberList.begin(); i != m_memberList.end(); ++i)
        {
            if ((*i)->isDisabledHeld())
                continue; // don't bother counting riders in the center calculation
            const Coord3D *objPos = (*i)->getPosition();
            center->x = objPos->x + center->x;
            center->y += objPos->y;
            center->z += objPos->z;
            ++count;
        }
    }

    center->x /= count;
    center->y /= count;
    center->z /= count;
    return count > 0;
}

